-- Idempotent PostgreSQL schema for Foxflix domain data.
-- Safe to run on startup: existing tables and data are preserved.
CREATE TABLE IF NOT EXISTS "Movies" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Title" text NOT NULL DEFAULT '',
    "Description" text NOT NULL DEFAULT '',
    "ReleaseYear" integer NOT NULL DEFAULT 0,
    "PosterUrl" text NOT NULL DEFAULT '',
    "BackdropUrl" text NOT NULL DEFAULT '',
    "TrailerUrl" text NULL,
    "Rating" double precision NOT NULL DEFAULT 0,
    "DurationMinutes" integer NOT NULL DEFAULT 0,
    "Genre" text NOT NULL DEFAULT '',
    "Country" text NOT NULL DEFAULT '',
    "AgeRating" integer NOT NULL DEFAULT 0,
    "VideoPath" text NULL,
    "PosterPath" text NULL,
    "VideoSizeBytes" bigint NULL,
    "VideoContentType" text NULL
);

CREATE TABLE IF NOT EXISTS "Series" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Title" text NOT NULL DEFAULT '',
    "Description" text NOT NULL DEFAULT '',
    "ReleaseYear" integer NOT NULL DEFAULT 0,
    "PosterUrl" text NOT NULL DEFAULT '',
    "BackdropUrl" text NOT NULL DEFAULT '',
    "TrailerUrl" text NULL,
    "Rating" double precision NOT NULL DEFAULT 0,
    "Genre" text NOT NULL DEFAULT '',
    "Country" text NOT NULL DEFAULT '',
    "AgeRating" integer NOT NULL DEFAULT 0,
    "SeasonsCount" integer NOT NULL DEFAULT 0,
    "PosterPath" text NULL
);

CREATE TABLE IF NOT EXISTS "Seasons" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "SeriesId" integer NOT NULL,
    "SeasonNumber" integer NOT NULL,
    "Title" text NOT NULL DEFAULT '',
    "PosterPath" text NULL,
    CONSTRAINT "FK_Seasons_Series_SeriesId"
        FOREIGN KEY ("SeriesId") REFERENCES "Series" ("Id") ON DELETE CASCADE
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_Seasons_SeriesId_SeasonNumber"
    ON "Seasons" ("SeriesId", "SeasonNumber");

CREATE TABLE IF NOT EXISTS "Episodes" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "SeasonId" integer NOT NULL,
    "EpisodeNumber" integer NOT NULL,
    "Title" text NOT NULL DEFAULT '',
    "Description" text NOT NULL DEFAULT '',
    "DurationMinutes" integer NOT NULL DEFAULT 0,
    "VideoPath" text NULL,
    "VideoSizeBytes" bigint NULL,
    "VideoContentType" text NULL,
    "PosterPath" text NULL,
    CONSTRAINT "FK_Episodes_Seasons_SeasonId"
        FOREIGN KEY ("SeasonId") REFERENCES "Seasons" ("Id") ON DELETE CASCADE
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_Episodes_SeasonId_EpisodeNumber"
    ON "Episodes" ("SeasonId", "EpisodeNumber");

CREATE TABLE IF NOT EXISTS "WatchHistories" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "UserId" text NOT NULL DEFAULT '',
    "MovieId" integer NOT NULL,
    "PositionSeconds" double precision NOT NULL DEFAULT 0,
    "DurationSeconds" double precision NOT NULL DEFAULT 0,
    "Completed" boolean NOT NULL DEFAULT false,
    "UpdatedAt" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "FK_WatchHistories_Movies_MovieId"
        FOREIGN KEY ("MovieId") REFERENCES "Movies" ("Id") ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS "IX_WatchHistories_MovieId"
    ON "WatchHistories" ("MovieId");
CREATE UNIQUE INDEX IF NOT EXISTS "IX_WatchHistories_UserId_MovieId"
    ON "WatchHistories" ("UserId", "MovieId");

CREATE TABLE IF NOT EXISTS "Favorites" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "UserId" text NOT NULL DEFAULT '',
    "MovieId" integer NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "FK_Favorites_Movies_MovieId"
        FOREIGN KEY ("MovieId") REFERENCES "Movies" ("Id") ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS "IX_Favorites_MovieId"
    ON "Favorites" ("MovieId");
CREATE UNIQUE INDEX IF NOT EXISTS "IX_Favorites_UserId_MovieId"
    ON "Favorites" ("UserId", "MovieId");

CREATE TABLE IF NOT EXISTS "TmdbFavorites" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "UserId" text NOT NULL DEFAULT '',
    "TmdbMovieId" integer NOT NULL,
    "Title" text NOT NULL DEFAULT '',
    "Overview" text NOT NULL DEFAULT '',
    "ReleaseDate" text NULL,
    "PosterUrl" text NULL,
    "Rating" double precision NOT NULL DEFAULT 0,
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS "IX_TmdbFavorites_UserId"
    ON "TmdbFavorites" ("UserId");
